import java.nio.file.*;import java.util.*;import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.tree.*;
public class Patch{public static void main(String[] a)throws Exception{ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[0]))).accept(c,0);Set<String> names=Set.of("hudBefore","hudSetup","hudState","width","height","texture","background");int n=0;for(MethodNode m:c.methods)for(AbstractInsnNode ins:m.instructions.toArray())if(ins instanceof MethodInsnNode v&&v.owner.equals("dev/zomboid/mts/Mechanics")&&names.contains(v.name)){v.owner="dev/zomboid/mts/HudTelemetry";n++;}if(n!=8)throw new AssertionError("Expected 8 HUD calls, got "+n);ClassWriter w=new ClassWriter(0);c.accept(w);Files.write(Path.of(a[1]),w.toByteArray());System.out.println("PASS all 8 HUD lifecycle hooks patched");}}
